    lsn                                                                      AS _version,
    op = 'd'                                                                 AS _is_deleted,
    ingested_at                                                              AS _synced_at
FROM bronze.cdc_events
WHERE source_table = 'seller_payouts';


-- product_reviews (state)
CREATE TABLE IF NOT EXISTS silver.product_reviews
(
    id             UUID,
    order_item_id  UUID,
    order_id       UUID,
    product_id     UUID,
    shop_id        UUID,
    customer_id    UUID,
    rating         Int32,
    comment        Nullable(String),
    created_at     DateTime64(6, 'UTC'),
    updated_at     DateTime64(6, 'UTC'),
    _version       UInt64,
    _is_deleted    UInt8,
    _synced_at     DateTime64(3, 'UTC')
)
ENGINE = ReplacingMergeTree(_version, _is_deleted)
ORDER BY id;

CREATE MATERIALIZED VIEW IF NOT EXISTS silver.mv_product_reviews TO silver.product_reviews AS
WITH if(op = 'd', before, after) AS row
SELECT
    toUUID(JSONExtractString(row, 'id'))                                     AS id,
    toUUID(JSONExtractString(row, 'order_item_id'))                          AS order_item_id,
    toUUID(JSONExtractString(row, 'order_id'))                               AS order_id,
    toUUID(JSONExtractString(row, 'product_id'))                             AS product_id,
    toUUID(JSONExtractString(row, 'shop_id'))                                AS shop_id,
    toUUID(JSONExtractString(row, 'customer_id'))                            AS customer_id,
    toInt32(JSONExtractInt(row, 'rating'))                                   AS rating,
    JSONExtract(row, 'comment', 'Nullable(String)')                          AS comment,
    parseDateTime64BestEffort(JSONExtractString(row, 'created_at'), 6, 'UTC') AS created_at,
    parseDateTime64BestEffort(JSONExtractString(row, 'updated_at'), 6, 'UTC') AS updated_at,
    lsn                                                                      AS _version,
    op = 'd'                                                                 AS _is_deleted,
    ingested_at                                                              AS _synced_at
FROM bronze.cdc_events
WHERE source_table = 'product_reviews';
